def shortestSubarrayOr(nums, k):
    cnt = [0] * 30
    cur = 0
    left = 0
    best = -1
    for right, x in enumerate(nums):
        for b in range(30):
            if (x >> b) & 1:
                cnt[b] += 1
                cur |= 1 << b
        while left <= right and cur >= k:
            length = right - left + 1
            if best < 0 or length < best:
                best = length
            y = nums[left]
            for b in range(30):
                if (y >> b) & 1:
                    cnt[b] -= 1
                    if cnt[b] == 0:
                        cur &= ~(1 << b)
            left += 1
    return best
